// DeleteUniqueIndexCache 删除索引存在的缓存
func (a *ArticleRepo) DeleteIndexCache(ctx context.Context, data ...*ai_boilerplate_model.Article) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, a.cache.Key(CacheArticleByConditionPrefix))
	keys = append(keys, a.cache.Key(CacheArticleUnscopedByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[a.cache.Key(CacheArticleByIDPrefix, item.ID)] = struct{}{}
			KeyMap[a.cache.Key(CacheArticleUnscopedByIDPrefix, item.ID)] = struct{}{}
			KeyMap[a.cache.Key(CacheArticleByStatusPrefix, item.Status)] = struct{}{}
			KeyMap[a.cache.Key(CacheArticleUnscopedByStatusPrefix, item.Status)] = struct{}{}
			KeyMap[a.cache.Key(CacheArticleByTitlePrefix, item.Title)] = struct{}{}
			KeyMap[a.cache.Key(CacheArticleUnscopedByTitlePrefix, item.Title)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := a.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
